"use strict";
// Renders one dashboard panel against fixture data, with a tiny fake DOM, and prints what it drew as JSON.
// Usage: node panel_runner.js <panel file> <context json file>. Shipped; learners do not edit this file.
const fs = require("fs");
const path = require("path");
const vm = require("vm");

class TextNode { constructor(text) { this.text = String(text); } }
class Node {
  constructor(tag) { this.tag = tag; this.children = []; this.attrs = {}; this.className = ""; }
  append(...kids) {
    for (const k of kids) {
      if (k == null || k === false) continue;
      this.children.push(typeof k === "object" ? k : new TextNode(k));
    }
  }
  replaceChildren(...kids) { this.children = []; this.append(...kids); }
  setAttribute(k, v) { this.attrs[k] = String(v); }
  addEventListener() {}
  set textContent(v) { this.children = [new TextNode(v)]; }
  get textContent() { return text(this); }
}
const text = (n) => (n instanceof TextNode ? n.text : n.children.map(text).join(""));
const walk = (n, f) => { f(n); if (n.children) n.children.forEach((c) => walk(c, f)); };

const document = {
  createElement: (tag) => new Node(tag),
  createElementNS: (ns, tag) => new Node(tag),
  getElementById: () => new Node("div"),
};
const panels = [];
const sandbox = { document, console, Dashboard: { register: (p) => panels.push(p), notBuilt: (el, label) => { const p = new Node("p"); p.append("Panel not built yet."); el.replaceChildren(p); } } };
sandbox.window = sandbox;
vm.createContext(sandbox);

const root = path.resolve(__dirname, "..", "..", "..");
const run = (file) => vm.runInContext(fs.readFileSync(file, "utf8"), sandbox, { filename: file });
run(path.join(root, "dashboard", "lib.js"));
run(path.resolve(process.argv[2]));

const data = JSON.parse(fs.readFileSync(process.argv[3], "utf8"));
const ctx = Object.assign({ lib: sandbox.DashLib, runs: [], kept: null, base: null, baseCases: [],
  loadCases: async (id) => (data.cases_by_run || {})[id] || [] }, data);
ctx.run = data.run ? Object.assign({}, data.run, { _cases: data.cases }) : null;
const host = new Node("div");
(async () => {
  await panels[0].render(ctx, host);
  const rows = [];
  walk(host, (n) => {
    if (n.tag !== "tr") return;
    const cells = n.children.filter((c) => c.tag === "td" || c.tag === "th").map(text);
    const bars = [];
    walk(n, (m) => { if (m.className === "bar-fill") bars.push(m.attrs.style); });
    rows.push({ cells, bars });
  });
  console.log(JSON.stringify({ title: panels[0].title, text: text(host), rows }));
})().catch((e) => { console.log(JSON.stringify({ error: String(e && e.message || e) })); process.exit(1); });
